import { MeshStandardNodeMaterial, Group, PlaneGeometry, Mesh, PointLight } from 'three/webgpu';
import { uv, vec3, vec4, mix } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const group = new Group();

  // 1. PALETTE & DESIGN PARAMS (Nova Atelier)
  const colors = {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10'
  };

  // 2. STAGE / BACKPLATE
  // This card represents "Journal card 1 label", structured like an engineered plate.
  const width = 2.4;
  const height = 1.3;
  const cardGeometry = new PlaneGeometry(width, height, 1, 1);

  // Material with TSL gradient surface and brushed metal reflection mappings
  const cardMaterial = new MeshStandardNodeMaterial({
    roughness: 0.52,
    metalness: 0.55,
    clearcoat: 0.15,
    clearcoatRoughness: 0.2
  });

  // Engineered gradient using TSL
  // Vertically transitioning from near-black surface to ink with a touch of the signal red accent
  const baseColor = vec3(0.043, 0.043, 0.063); // #0b0b10
  const topColor = vec3(0.086, 0.086, 0.114);  // #16161d
  const accentColor = vec3(1.0, 0.165, 0.22); // #ff2a38

  const vUv = uv();
  const verticalGradient = mix(baseColor, topColor, vUv.y);
  // Add a very subtle horizontal accent signal at the left edge
  const leftEdgeSignal = mix(accentColor, vec3(0.0), vUv.x.mul(10.0).clamp(0.0, 1.0));

  cardMaterial.colorNode = vec4(mix(verticalGradient, accentColor, leftEdgeSignal.mul(0.15)), 1.0);

  // Load brushed-metal map
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((texture) => {
      texture.wrapS = THREE.RepeatWrapping;
      texture.wrapT = THREE.RepeatWrapping;
      texture.repeat.set(2, 2);
      cardMaterial.roughnessMap = texture;
      cardMaterial.metalnessMap = texture;
      cardMaterial.needsUpdate = true;
    });
  }

  const cardMesh = new Mesh(cardGeometry, cardMaterial);
  cardMesh.castShadow = true;
  cardMesh.receiveShadow = true;
  group.add(cardMesh);

  // 3. ACCENT BEVEL OVERLAY (Precision look)
  const lineGeom = new PlaneGeometry(0.04, height - 0.1);
  const lineMat = new MeshStandardNodeMaterial({
    color: colors.accent,
    emissive: colors.accent,
    emissiveIntensity: 0.6,
    roughness: 0.2
  });
  const lineMesh = new Mesh(lineGeom, lineMat);
  lineMesh.position.set(-width / 2 + 0.1, 0, 0.01);
  group.add(lineMesh);

  // 4. TEXT CONTENT
  // Extract text config
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const textItem = items.find(item => item.role === 'headline') ?? { text: 'Journal 1' };

  // Render text content using ctx.fontAtlas
  const textLabel = ctx.fontAtlas.createText(textItem.text, {
    fontSize: 48,
    color: colors.paper,
    align: 'left'
  });
  // Position text to fit nicely on the card plate surface
  textLabel.position.set(-width / 2 + 0.25, -0.08, 0.02);
  group.add(textLabel);

  // 5. LOCAL PRODUCT LIGHTS (Rim & Accent to make the metal pop)
  const rimLight = new PointLight(colors.paper, 1.2, 5);
  rimLight.position.set(2, 2, 1.5);
  group.add(rimLight);

  const accentLight = new PointLight(colors.accent, 0.8, 4);
  accentLight.position.set(-2, -1, 1);
  group.add(accentLight);

  // 6. ENTRANCE ANIMATION (GSAP - Rise and weighted settle)
  const tl = gsap.timeline();
  group.position.y += 0.3;
  group.scale.set(0.95, 0.95, 0.95);

  tl.to(group.position, {
    y: '-=0.3',
    duration: 0.9,
    ease: 'power4.out'
  });
  tl.to(group.scale, {
    x: 1,
    y: 1,
    z: 1,
    duration: 0.9,
    ease: 'power4.out',
    delay: 0.05
  });

  // Cleanup handler
  group.userData.cleanup = function () {
    if (tl) tl.kill();
    cardGeometry.dispose();
    cardMaterial.dispose();
    lineGeom.dispose();
    lineMat.dispose();
  };

  return group;
}
